<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Resources\PatientResource; use App\Http\Responses\ApiResponse; use App\Models\Patient; use Illuminate\Http\Request;
class PatientController extends Controller { public function index(){ $p=Patient::with('user')->latest()->paginate(10); return ApiResponse::success(PatientResource::collection($p)->response()->getData(true)['data'],'Data pasien',200,['pagination'=>['current_page'=>$p->currentPage(),'per_page'=>$p->perPage(),'total'=>$p->total(),'last_page'=>$p->lastPage(),'next_page_url'=>$p->nextPageUrl(),'prev_page_url'=>$p->previousPageUrl()]]); } public function show(Patient $patient){ $u=request()->user(); if(!$u->isRole('admin') && $u->patient?->id!==$patient->id) return ApiResponse::error('Forbidden',403); return ApiResponse::success(new PatientResource($patient->load('user'))); } public function update(Request $r, Patient $patient){ $u=$r->user(); if(!$u->isRole('admin') && $u->patient?->id!==$patient->id) return ApiResponse::error('Forbidden',403); $data=$r->validate(['date_of_birth'=>['nullable','date'],'address'=>['nullable','string'],'phone'=>['nullable','string','max:30']]); $patient->update($data); return ApiResponse::success(new PatientResource($patient->load('user')),'Pasien diperbarui'); } }
